// Build-time embedded migration bundle.
//
// **AUTO-GENERATED by `scripts/gen-embedded-migrations.ts`.**  Do not
// edit by hand — the codegen rebuilds this file from
// `meta/_journal.json` on every `bun run db:gen-embedded`. The CI
// drift check (`bun run check:embedded-drift`) fails if the
// committed file disagrees with the regenerated output.
//
// We import each migration's raw SQL as text and the journal as JSON.
// `bun build --compile` inlines the contents of every imported text /
// JSON asset into the binary, so the runtime never reads the
// filesystem and the engine + migration set ship as a single artifact.
//
// Drift safeguard: `migrate-embedded-bundle.test.ts` re-reads the
// on-disk SQL files at test time and asserts every embedded body's
// SHA-256 matches the file. CI fails loudly if a new migration is
// added but not registered here.

import { createHash } from "node:crypto";
import sql0000V6Baseline from "./0000_v6_baseline.sql" with { type: "text" };
import sql0001CondemnedMaestro from "./0001_condemned_maestro.sql" with { type: "text" };
import sql0002KindHumanRobot from "./0002_kind_human_robot.sql" with { type: "text" };
import sql0003MarvelousStranger from "./0003_marvelous_stranger.sql" with { type: "text" };
import sql0004FlakyZarek from "./0004_flaky_zarek.sql" with { type: "text" };
import sql0005M2mOauthCredentialMode from "./0005_m2m_oauth_credential_mode.sql" with { type: "text" };
import sql0006RemarkableNamor from "./0006_remarkable_namor.sql" with { type: "text" };
import sql0007SlimyAbomination from "./0007_slimy_abomination.sql" with { type: "text" };
import sql0008OutstandingMakkari from "./0008_outstanding_makkari.sql" with { type: "text" };
import sql0009AuthoringCapabilityCandidate from "./0009_authoring_capability_candidate.sql" with { type: "text" };
import sql0010LocalInviteProvisioning from "./0010_local_invite_provisioning.sql" with { type: "text" };
import sql0011AmbiguousFalcon from "./0011_ambiguous_falcon.sql" with { type: "text" };
import sql0012McpTaskHeartbeat from "./0012_mcp_task_heartbeat.sql" with { type: "text" };
import journalMeta from "./meta/_journal.json" with { type: "json" };

interface JournalEntry {
  idx: number;
  tag: string;
  when: number;
  breakpoints?: boolean;
}

interface Journal {
  version: string;
  dialect: string;
  entries: JournalEntry[];
}

export interface EmbeddedMigration {
  idx: number;
  tag: string;
  when: number;
  hash: string;
  statements: string[];
}

const SQL_BY_TAG: Record<string, string> = {
  "0000_v6_baseline": sql0000V6Baseline,
  "0001_condemned_maestro": sql0001CondemnedMaestro,
  "0002_kind_human_robot": sql0002KindHumanRobot,
  "0003_marvelous_stranger": sql0003MarvelousStranger,
  "0004_flaky_zarek": sql0004FlakyZarek,
  "0005_m2m_oauth_credential_mode": sql0005M2mOauthCredentialMode,
  "0006_remarkable_namor": sql0006RemarkableNamor,
  "0007_slimy_abomination": sql0007SlimyAbomination,
  "0008_outstanding_makkari": sql0008OutstandingMakkari,
  "0009_authoring_capability_candidate": sql0009AuthoringCapabilityCandidate,
  "0010_local_invite_provisioning": sql0010LocalInviteProvisioning,
  "0011_ambiguous_falcon": sql0011AmbiguousFalcon,
  "0012_mcp_task_heartbeat": sql0012McpTaskHeartbeat,
};

const journal = journalMeta as unknown as Journal;

function buildBundle(): EmbeddedMigration[] {
  return journal.entries
    .slice()
    .sort((a, b) => a.idx - b.idx)
    .map((e) => {
      const raw = SQL_BY_TAG[e.tag];
      if (raw === undefined) {
        // Caught by `migrate-embedded-bundle.test.ts` in CI long before
        // a binary ships.
        throw new Error(
          `embedded.ts is out of sync with meta/_journal.json: missing SQL for tag '${e.tag}'`,
        );
      }
      const statements = raw
        .split("--> statement-breakpoint")
        .map((s) => s.trim())
        .filter((s) => s.length > 0);
      const hash = createHash("sha256").update(raw).digest("hex");
      return { idx: e.idx, tag: e.tag, when: e.when, hash, statements };
    });
}

export const EMBEDDED_MIGRATIONS: readonly EmbeddedMigration[] = buildBundle();
export const EMBEDDED_JOURNAL: Journal = journal;
